-- 🌟 99 noms d'Allah (27/11/2026, 2ᵉ série) — fichier GÉNÉRÉ par scripts/fiches-99-noms/generer.py (ne pas modifier à la main).
-- 1. Fiches ADULTES de Nadia : lot 3 complet (appli 11 à 20) + lot 11 (ChatGPT 91 à 98 = appli 92 à 99, décalage d'Al-Ahad).
--    11 et 12 : la version du lot 3 coupé est REMPLACÉE (seulement si elle n'a pas été modifiée depuis : 1ʳᵉ section « Signification »).
--    Toujours sans fiche de Nadia : 67 Al-Ahad (garde l'ancienne fiche).
-- 2. Version ENFANT (fiche_enfant) pour chaque nom qui a une fiche adulte, marquée « à relire » ; écrite seulement si la place est vide.
-- 3. Table allah_names_version_eleve : version des 99 noms choisie par l'enseignante pour un élève (auto / petit / enfant / adulte).
-- Sécurité : chaque ligne n'est écrite que si le numéro ET la translittération de l'appli correspondent.
-- À appliquer avec `supabase db query --linked -f` (JAMAIS `db push`). Relancer = sans effet.

create table if not exists public.allah_names_version_eleve (
  user_id uuid primary key references auth.users(id) on delete cascade,
  version text not null default 'auto' check (version in ('auto', 'petit', 'enfant', 'adulte')),
  updated_at timestamptz not null default now()
);
comment on table public.allah_names_version_eleve is '99 noms : version enfant / adulte choisie par l''enseignante pour un élève (auto = selon l''âge).';
alter table public.allah_names_version_eleve enable row level security;
drop policy if exists allah_names_version_lecture on public.allah_names_version_eleve;
create policy allah_names_version_lecture on public.allah_names_version_eleve for select to authenticated
  using (user_id = auth.uid() or public.has_role(auth.uid(), 'admin'::app_role));
drop policy if exists allah_names_version_admin on public.allah_names_version_eleve;
create policy allah_names_version_admin on public.allah_names_version_eleve for all to authenticated
  using (public.has_role(auth.uid(), 'admin'::app_role)) with check (public.has_role(auth.uid(), 'admin'::app_role));
do $$ begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'allah_names_version_eleve') then
    alter publication supabase_realtime add table public.allah_names_version_eleve;
  end if;
end $$;

update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْخَالِقُ", "translit": "Al-Khâliq", "traduction": "Le Créateur, Celui qui crée toute chose.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Khâliq, le Créateur de toute existence. Il a créé les cieux, la terre, les êtres vivants et tout ce qui existe.\n\nSa création ne ressemble pas à celle des êtres humains : nous transformons des éléments déjà existants, tandis qu'Allah est le Créateur de toute chose. Rien ne Lui est impossible et rien n'existe indépendamment de Lui.\n\nCe Nom nous invite à contempler la création et à reconnaître la grandeur de Celui qui en est à l'origine."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Reconnaître qu'Allah est l'unique Créateur.\n- Être reconnaissant pour la vie et les bienfaits reçus.\n- Méditer sur les merveilles de la création.\n- Ne pas attribuer à une créature un pouvoir de création comparable à celui d'Allah."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "اللَّهُ خَالِقُ كُلِّ شَيْءٍ", "traduction": "« Allah est le Créateur de toute chose. »", "ref": "Coran, sourate Az-Zumar (39), verset 62.", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre preuve", "arabe": "هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ", "traduction": "« Il est Allah, le Créateur, Celui qui donne un commencement à toute chose, le Formateur. »", "ref": "Coran, sourate Al-Hashr (59), verset 24.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on contemple la création, qu'on remercie Allah pour la vie ou qu'on Lui demande de nous guider vers ce qui est bon."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Khâliq, Toi qui as créé toute chose, guide-moi vers ce qui Te satisfait et fais de moi un serviteur reconnaissant. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 11}$fiche$::jsonb where display_order = 11 and transliteration = 'Al-Khâliq' and (fiche_adulte is null or fiche_adulte->'sections'->0->>'titre' = 'Signification');
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْبَارِئُ", "translit": "Al-Bâri'", "traduction": "Celui qui donne existence à la création, Celui qui fait surgir les créatures.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Bâri'. Il fait exister les créatures selon Sa volonté et Sa sagesse. Il leur donne une existence propre et les distingue les unes des autres.\n\nCe Nom est associé à Al-Khâliq et Al-Musawwir dans le verset 24 de la sourate Al-Hashr.\n\nOn peut comprendre ces trois appellations comme évoquant des aspects complémentaires de la création : Allah crée, fait exister et donne leur forme aux créatures. Il ne faut toutefois pas enfermer les attributs divins dans une explication humaine limitée."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Reconnaître que notre existence dépend entièrement d'Allah.\n- Contempler la diversité et la richesse de la création.\n- Être humble devant la puissance du Créateur.\n- Remercier Allah pour notre existence et nos capacités."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ", "traduction": "« Il est Allah, le Créateur, Celui qui donne un commencement à toute chose, le Formateur. »", "ref": "Coran, sourate Al-Hashr (59), verset 24.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on médite sur notre existence, la naissance et la diversité des êtres vivants, ou lorsqu'on remercie Allah pour Ses bienfaits."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Bâri', Toi qui as donné existence à toute chose, accorde-moi une vie remplie de foi et d'obéissance. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 12}$fiche$::jsonb where display_order = 12 and transliteration = 'Al-Bâri''' and (fiche_adulte is null or fiche_adulte->'sections'->0->>'titre' = 'Signification');
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْمُصَوِّرُ", "translit": "Al-Musawwir", "traduction": "Celui qui donne aux créatures leur forme et leur apparence.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Musawwir. Il donne à chaque créature sa forme, ses caractéristiques et son apparence selon Sa sagesse.\n\nLes êtres humains, les animaux, les plantes et toutes les créatures présentent une diversité extraordinaire. Cette diversité témoigne de la perfection de la création d'Allah.\n\nAucune créature ne possède une apparence qui échappe à Sa connaissance ou à Sa volonté."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Contempler la diversité des créatures.\n- Reconnaître la sagesse d'Allah dans la création.\n- Ne pas mépriser les personnes en raison de leur apparence.\n- Remercier Allah pour le corps et les capacités qu'Il nous a accordés."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "هُوَ اللَّهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ", "traduction": "« Il est Allah, le Créateur, Celui qui donne un commencement à toute chose, le Formateur. »", "ref": "Coran, sourate Al-Hashr (59), verset 24.", "degre": "coran", "texte": null}, {"type": "preuve", "titre": "Autre référence", "arabe": "يُصَوِّرُكُمْ فِي الْأَرْحَامِ كَيْفَ يَشَاءُ", "traduction": "« Il vous façonne dans les matrices comme Il veut. »", "ref": "Coran, sourate Âl 'Imrân (3), verset 6.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on contemple la création, qu'on remercie Allah pour les bienfaits de notre corps ou qu'on Lui demande de nous embellir par la foi et les bonnes actions."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Musawwir, embellis mon cœur par la foi, améliore mon comportement et fais de moi une personne reconnaissante. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 13}$fiche$::jsonb where display_order = 13 and transliteration = 'Al-Musawwir' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْغَفَّارُ", "translit": "Al-Ghaffâr", "traduction": "Celui qui pardonne abondamment et à maintes reprises.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Ghaffâr. Son pardon est immense et Il pardonne les péchés de ceux qui reviennent sincèrement vers Lui.\n\nCe Nom exprime l'immensité et la répétition du pardon d'Allah. Même lorsque le serviteur commet plusieurs fautes, il ne doit jamais désespérer de Sa miséricorde s'il revient sincèrement vers Lui.\n\nLe pardon d'Allah ne doit cependant pas être un prétexte pour banaliser les péchés. Le croyant doit s'efforcer de les délaisser et de se repentir sincèrement."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Ne jamais désespérer du pardon d'Allah.\n- Reconnaître ses fautes et demander pardon.\n- Se repentir sincèrement et éviter de persister volontairement dans le péché.\n- Apprendre à pardonner aux autres lorsque cela est juste et possible."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَىٰ", "traduction": "« Et Je suis Grand Pardonneur envers celui qui se repent, croit, accomplit de bonnes œuvres puis suit le bon chemin. »", "ref": "Coran, sourate Tâ-Hâ (20), verset 82.", "degre": "coran", "texte": "Autre référence : Coran, sourate Ghâfir (40), verset 42."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on regrette un péché, qu'on demande pardon à Allah et qu'on souhaite retrouver le chemin de l'obéissance."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Ghaffâr, pardonne mes fautes, accepte mon repentir et aide-moi à ne pas retourner vers ce qui Te déplaît. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 14}$fiche$::jsonb where display_order = 14 and transliteration = 'Al-Ghaffâr' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْقَهَّارُ", "translit": "Al-Qahhâr", "traduction": "Le Dominateur absolu, Celui à qui rien ne peut résister.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Qahhâr. Sa puissance domine toute chose et aucune créature ne peut s'opposer à Son pouvoir.\n\nTout ce qui existe est soumis à Sa souveraineté. Aucun être, aucune force et aucun événement ne peuvent échapper à Son autorité.\n\nCe Nom nous rappelle que la puissance d'Allah est absolue, tandis que celle des créatures est limitée et temporaire."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Reconnaître la puissance absolue d'Allah.\n- Ne pas se laisser impressionner par la puissance des êtres humains.\n- Éviter l'arrogance et l'oppression.\n- Se soumettre humblement à Allah."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ", "traduction": "« Dis : Allah est le Créateur de toute chose, et Il est l'Unique, le Dominateur suprême. »", "ref": "Coran, sourate Ar-Ra'd (13), verset 16.", "degre": "coran", "texte": "Autre référence : Coran, sourate Ibrâhîm (14), verset 48."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on souhaite se rappeler que rien ne peut résister à Sa puissance, demander Son aide face à une difficulté ou Lui demander de nous préserver de l'injustice."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Qahhâr, Toi dont la puissance domine toute chose, aide-moi à maîtriser mon âme et à rester sur le droit chemin. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 15}$fiche$::jsonb where display_order = 15 and transliteration = 'Al-Qahhâr' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْوَهَّابُ", "translit": "Al-Wahhâb", "traduction": "Le Grand Donateur, Celui qui accorde Ses dons généreusement.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Wahhâb. Il accorde Ses bienfaits à Ses serviteurs par Sa générosité, sans avoir besoin de recevoir quoi que ce soit en retour.\n\nIl donne la vie, la santé, la subsistance, la connaissance, la foi et de nombreux bienfaits visibles et invisibles.\n\nCe Nom nous rappelle que tout ce que nous possédons est un don d'Allah et que nous devons Lui en être reconnaissants."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Remercier Allah pour Ses bienfaits.\n- Ne pas considérer les dons reçus comme un droit qui nous serait dû.\n- Demander à Allah les bienfaits utiles à notre vie et à notre foi.\n- Être généreux avec les autres selon nos possibilités."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "إِنَّكَ أَنْتَ الْوَهَّابُ", "traduction": "« C'est Toi, certes, le Grand Donateur. »", "ref": "Coran, sourate Âl 'Imrân (3), verset 8.", "degre": "coran", "texte": "Autre référence : Coran, sourate Sâd (38), verset 9."}, {"type": "prophetique", "titre": "Invocation coranique", "arabe": "رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ الْوَهَّابُ", "phonetique": null, "traduction": "« Seigneur, ne laisse pas nos cœurs dévier après nous avoir guidés et accorde-nous une miséricorde venant de Toi. C'est Toi, certes, le Grand Donateur. »", "ref": "Coran, sourate Âl 'Imrân (3), verset 8.", "degre": "coran", "texte": null, "note": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande à Allah un bienfait, une bonne descendance, la connaissance bénéfique, la foi ou Sa miséricorde."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Wahhâb, accorde-moi Tes bienfaits, une foi sincère et une connaissance utile. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 16}$fiche$::jsonb where display_order = 16 and transliteration = 'Al-Wahhâb' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الرَّزَّاقُ", "translit": "Ar-Razzâq", "traduction": "Le Pourvoyeur absolu, Celui qui accorde la subsistance.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Ar-Razzâq. Il est Celui qui pourvoit aux besoins de toutes Ses créatures.\n\nLa subsistance ne se limite pas à l'argent : elle comprend la nourriture, l'eau, la santé, la famille, la connaissance, la tranquillité et tous les bienfaits dont nous profitons.\n\nLe croyant doit rechercher sa subsistance par des moyens licites, tout en sachant que son véritable Pourvoyeur est Allah."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Placer sa confiance en Allah concernant sa subsistance.\n- Rechercher des moyens de gagner sa vie de manière licite.\n- Être reconnaissant pour les bienfaits reçus.\n- Ne pas envier les richesses des autres.\n- Se rappeler que la subsistance d'Allah ne se limite pas aux biens matériels."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "إِنَّ اللَّهَ هُوَ الرَّزَّاقُ ذُو الْقُوَّةِ الْمَتِينُ", "traduction": "« Allah est certes le Grand Pourvoyeur, le Détenteur de la force, l'Inébranlable. »", "ref": "Coran, sourate Adh-Dhâriyât (51), verset 58.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande une subsistance licite, qu'on traverse des difficultés financières ou qu'on souhaite remercier Allah pour les bienfaits reçus."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Ar-Razzâq, accorde-moi une subsistance licite, abondante et bénie, et rends-moi reconnaissant pour Tes bienfaits. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 17}$fiche$::jsonb where display_order = 17 and transliteration = 'Ar-Razzâq' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْفَتَّاحُ", "translit": "Al-Fattâh", "traduction": "Celui qui ouvre les portes du bien et qui juge avec vérité.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Fattâh. Il ouvre les portes de Sa miséricorde, de Sa sagesse et de Ses bienfaits. Il accorde la réussite à qui Il veut et tranche avec justice entre Ses serviteurs.\n\nIl est Celui qui connaît parfaitement les situations et qui juge sans injustice.\n\nCe Nom nous rappelle que les solutions, les issues favorables et la véritable réussite viennent d'Allah."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Demander à Allah de nous ouvrir les portes du bien.\n- Lui demander de faciliter les difficultés.\n- Rechercher la vérité et la justice.\n- Ne pas désespérer lorsqu'une porte semble fermée.\n- Faire confiance à Sa sagesse."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ", "traduction": "« Dis : Notre Seigneur nous réunira, puis Il tranchera entre nous en toute vérité. C'est Lui le Grand Juge, l'Omniscient. »", "ref": "Coran, sourate Saba' (34), verset 26.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande à Allah de faciliter une situation, d'ouvrir une porte vers le bien, de nous guider dans une décision ou de nous accorder une issue favorable."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Fattâh, ouvre-moi les portes du bien, facilite mes affaires et guide-moi vers les décisions qui Te satisfont. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 18}$fiche$::jsonb where display_order = 18 and transliteration = 'Al-Fattâh' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْعَلِيمُ", "translit": "Al-'Alîm", "traduction": "L'Omniscient, Celui qui sait absolument toute chose.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-'Alîm. Sa connaissance est parfaite, complète et illimitée.\n\nIl connaît le passé, le présent et l'avenir. Rien ne Lui échappe, qu'il s'agisse des choses visibles ou invisibles, des paroles prononcées, des intentions ou des pensées les plus secrètes.\n\nLa connaissance humaine est limitée et acquise progressivement, tandis que la connaissance d'Allah est parfaite et n'a ni commencement ni fin."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Être sincère dans nos intentions, car Allah connaît nos cœurs.\n- Ne pas croire que nos actes cachés échappent à Sa connaissance.\n- Reconnaître les limites de notre propre savoir.\n- Demander à Allah une connaissance bénéfique.\n- Éviter de juger les autres sur ce que nous ignorons de leurs intentions."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ", "traduction": "« Et Il est Omniscient de toute chose. »", "ref": "Coran, sourate Al-Baqara (2), verset 29.", "degre": "coran", "texte": "Autre référence : Coran, sourate Al-An'âm (6), verset 101."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on demande à Allah de nous guider dans une décision, de nous accorder une connaissance utile ou de nous aider à agir avec sincérité."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-'Alîm, Toi qui connais toute chose, accorde-moi une connaissance bénéfique, purifie mes intentions et guide-moi vers la vérité. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 19}$fiche$::jsonb where display_order = 19 and transliteration = 'Al-''Alîm' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْقَابِضُ", "translit": "Al-Qâbid", "traduction": "Celui qui retient et restreint selon Sa sagesse.", "provenance": "Sunna — hadith qualifié de « hasan sahih » par At-Tirmidhî.", "statut": "etabli", "classement": "sunna", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui qui peut restreindre ou retenir certains bienfaits selon Sa sagesse et Son décret.\n\nCe Nom est associé à Al-Bâsit, Celui qui étend et accorde largement. Allah peut accorder une subsistance abondante à certains moments et la restreindre à d'autres.\n\nCela ne signifie pas que chaque difficulté financière ou chaque privation est une punition. Nous ne connaissons pas toujours la sagesse qui se trouve derrière les événements.\n\nLe croyant doit continuer à faire les efforts licites, à demander l'aide d'Allah et à garder confiance en Lui."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Reconnaître qu'Allah est le Maître de toute subsistance.\n- Faire preuve de patience lorsque les ressources sont limitées.\n- Ne pas désespérer pendant les périodes difficiles.\n- Ne pas oublier Allah lorsque les bienfaits sont abondants.\n- Être reconnaissant et généreux selon ses possibilités."}, {"type": "prophetique", "titre": "Preuve dans la Sunna", "arabe": "إِنَّ اللَّهَ هُوَ الْمُسَعِّرُ الْقَابِضُ الْبَاسِطُ الرَّزَّاقُ", "phonetique": "Inna Allâha huwa al-Mus'iru al-Qâbidu al-Bâsitu ar-Razzâq.", "traduction": "« Allah est Celui qui fixe les prix, Celui qui retient, Celui qui étend et le Pourvoyeur. »", "ref": "Jâmi' At-Tirmidhî, hadith 1314.", "degre": "sahih", "texte": "Le Prophète ﷺ a enseigné qu'Allah est notamment Al-Qâbid, Al-Bâsit et Ar-Razzâq.\n\nLe hadith rapporte qu'à une période où les prix avaient augmenté, des personnes demandèrent au Prophète ﷺ de fixer les prix. Il répondit :", "note": "Authenticité : At-Tirmidhî qualifie ce hadith de « hasan sahih ». Il est également classé authentique dans l'édition de Dârussalâm.\n\nPrécision importante : Ce hadith constitue une preuve dans la Sunna pour les termes Al-Qâbid, Al-Bâsit et Ar-Razzâq. Il faut donc distinguer cette attestation prophétique des noms uniquement déduits d'une action coranique."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on traverse une période de restriction ou de difficulté, tout en demandant à Allah de nous accorder une subsistance licite et suffisante."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui accordes et qui retiens selon Ta sagesse, facilite mes affaires, accorde-moi une subsistance licite et rends-moi reconnaissant dans toutes les situations. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "SUNNA", "texte": "Attesté dans un hadith qualifié de « hasan sahih » par At-Tirmidhî. Le terme apparaît explicitement dans la parole prophétique rapportée."}], "numero_source": 20}$fiche$::jsonb where display_order = 20 and transliteration = 'Al-Qâbid' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "النَّافِعُ", "translit": "An-Nâfi'", "traduction": "Celui qui accorde le bénéfice et le bienfait.", "provenance": "Sens attesté dans le Coran ; Nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Celui de qui proviennent les bienfaits et les bénéfices. Rien ne peut apporter un bien véritable indépendamment de Sa volonté.\n\nLa santé, la connaissance, la subsistance, la foi et les occasions de faire le bien sont autant de bienfaits que le serviteur reçoit par la grâce d'Allah.\n\nCette appellation apparaît dans les listes traditionnelles des 99 noms. Toutefois, la forme exacte « An-Nâfi' » comme Nom divin indépendant n'est pas explicitement établie par un texte clair du Coran ou de la Sunna authentique. Il faut donc distinguer le sens général, qui est vrai, de l'établissement de cette appellation comme Nom."}, {"type": "texte", "titre": "Ce que cette appellation nous enseigne", "texte": "- Reconnaître que les bienfaits viennent d'Allah.\n- Être reconnaissant pour les choses qui nous sont accordées.\n- Demander à Allah ce qui est bénéfique pour notre foi et notre vie.\n- Ne pas confondre un avantage matériel avec un bien véritable."}, {"type": "preuve", "titre": "Preuve liée au sens dans le Coran", "arabe": "وَإِنْ يَمْسَسْكَ اللَّهُ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ", "traduction": "« Si Allah te touche d'un bienfait, nul ne peut repousser Sa grâce. »", "ref": "Coran, sourate Yûnus (10), verset 107.", "degre": "coran", "texte": "Précision : Le verset affirme que le bienfait vient d'Allah et que personne ne peut empêcher Sa grâce. Il ne contient pas la forme exacte « An-Nâfi' »."}, {"type": "texte", "titre": "Quand évoquer cette appellation", "texte": "Lorsqu'on remercie Allah pour Ses bienfaits ou qu'on Lui demande de nous accorder ce qui est bénéfique dans notre religion et notre vie."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, accorde-moi ce qui est bénéfique pour ma foi, ma vie et mon avenir, et éloigne de moi ce qui pourrait me nuire. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "STATUT DISCUTÉ", "texte": "Sens général attesté dans le Coran ; statut de « An-Nâfi' » comme Nom divin indépendant discuté. Mention de prudence obligatoire."}], "numero_source": 91}$fiche$::jsonb where display_order = 92 and transliteration = 'An-Nâfi''' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "النُّورُ", "translit": "An-Nûr", "traduction": "La Lumière.", "provenance": "Coran — appellation explicitement attestée.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "An-Nûr est une appellation coranique d'Allah. Allah est la Lumière des cieux et de la terre. Il guide Ses serviteurs vers la vérité et éclaire leurs cœurs par la foi.\n\nLa lumière divine ne doit pas être imaginée comme une lumière créée ou comparée à celle du soleil, d'une lampe ou d'un objet. Allah n'est comparable à aucune de Ses créatures.\n\nLe verset de la Lumière, dans la sourate An-Nûr, évoque la lumière d'Allah et donne une parabole magnifique pour faire comprendre la guidance."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Demander à Allah de guider notre cœur.\n- Rechercher la lumière de la foi et de la connaissance.\n- Éviter les chemins qui nous éloignent de la vérité.\n- Reconnaître que la véritable guidance vient d'Allah."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ", "traduction": "« Allah est la Lumière des cieux et de la terre. »", "ref": "Coran, sourate An-Nûr (24), verset 35.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par cette appellation", "texte": "Lorsqu'on demande la guidance, la clarté du cœur, la foi et la protection contre l'égarement."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, éclaire mon cœur par la foi, guide-moi vers la vérité et éloigne-moi de tout ce qui pourrait m'égarer. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Appellation explicitement attestée dans le Coran. Son interprétation doit respecter la transcendance d'Allah et ne pas assimiler Sa lumière à une lumière créée."}], "numero_source": 92}$fiche$::jsonb where display_order = 93 and transliteration = 'An-Nûr' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْهَادِي", "translit": "Al-Hâdî", "traduction": "Le Guide, Celui qui guide vers le droit chemin.", "provenance": "Sens de la guidance attesté dans le Coran ; forme nominale à distinguer.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Hâdî. Il guide Ses serviteurs vers la vérité et leur montre le chemin qui mène à Son agrément.\n\nLa guidance est un immense bienfait. Elle permet au croyant de distinguer le vrai du faux, de reconnaître la vérité et de suivre le chemin de l'obéissance.\n\nAllah guide qui Il veut selon Sa sagesse. Le serviteur doit Lui demander constamment la guidance et faire les efforts nécessaires pour suivre la vérité."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Demander régulièrement à Allah de nous guider.\n- Ne jamais considérer notre foi comme acquise.\n- Rechercher la connaissance religieuse fiable.\n- Accepter la vérité même lorsqu'elle va à l'encontre de nos habitudes.\n- Demander à Allah de raffermir notre cœur."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ آمَنُوا إِلَىٰ صِرَاطٍ مُسْتَقِيمٍ", "traduction": "« Allah guide certes ceux qui ont cru vers un chemin droit. »", "ref": "Coran, sourate Al-Hajj (22), verset 54.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par cette appellation", "texte": "Lorsqu'on demande à Allah de nous guider dans nos décisions, de nous préserver de l'égarement ou de raffermir notre foi."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, guide-moi vers la vérité, raffermis mon cœur dans la foi et aide-moi à suivre le chemin qui Te satisfait. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "FORME NOMINALE À DISTINGUER", "texte": "Le sens de la guidance divine est explicitement attesté dans le Coran. La forme nominale « Al-Hâdî » est une appellation traditionnelle ; le verset cité emploie la forme « la-hâdî » dans une phrase descriptive."}], "numero_source": 93}$fiche$::jsonb where display_order = 94 and transliteration = 'Al-Hâdî' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْبَدِيعُ", "translit": "Al-Badî'", "traduction": "L'Initiateur parfait, Celui qui crée sans modèle préalable.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Badî'. Il est Celui qui a créé les cieux et la terre sans avoir besoin d'un modèle précédent ni d'un exemple à reproduire.\n\nLa création d'Allah est le fruit de Sa puissance et de Sa sagesse. Il n'a besoin d'aucune aide ni d'aucun matériau préexistant pour créer.\n\nCe Nom nous invite à méditer sur l'immensité de la création et sur la perfection du Créateur."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Reconnaître qu'Allah est à l'origine de toute création.\n- Contempler les merveilles de l'univers.\n- Ne pas attribuer à une créature une puissance créatrice comparable à celle d'Allah.\n- Faire preuve d'humilité devant la grandeur du Créateur."}, {"type": "preuve", "titre": "Preuves dans le Coran", "arabe": "بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ", "traduction": "« Il est l'Initiateur des cieux et de la terre. »", "ref": "Coran, sourate Al-Baqara (2), verset 117.", "degre": "coran", "texte": "Autre référence : Coran, sourate Al-An'âm (6), verset 101."}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on médite sur la création, qu'on reconnaît Sa puissance ou qu'on Lui demande de nous guider vers de bonnes initiatives."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Badî', Toi qui as créé les cieux et la terre sans modèle préalable, guide-moi vers ce qui est bon et bénéfique. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 94}$fiche$::jsonb where display_order = 95 and transliteration = 'Al-Badî''' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْبَاقِي", "translit": "Al-Bâqî", "traduction": "Celui qui demeure éternellement.", "provenance": "Sens de la permanence attesté dans le Coran ; Nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah demeure éternellement. Tout ce qui appartient à la création est temporaire et appelé à disparaître selon Son décret, tandis qu'Allah ne cesse jamais d'exister.\n\nCe Nom nous rappelle la différence entre le Créateur et les créatures : notre existence est limitée, mais Allah est éternel.\n\nLa forme exacte « Al-Bâqî » apparaît dans les listes traditionnelles. Le Coran affirme clairement qu'Allah demeure, mais la forme nominale exacte comme Nom divin indépendant est discutée par les savants."}, {"type": "texte", "titre": "Ce que cette appellation nous rappelle", "texte": "- La vie d'ici-bas est temporaire.\n- Les biens matériels ne sont pas éternels.\n- Il faut préparer notre rencontre avec Allah.\n- Les œuvres accomplies sincèrement pour Allah ont une valeur qui dépasse les plaisirs éphémères."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَيَبْقَىٰ وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ", "traduction": "« Seule subsistera la Face de ton Seigneur, plein de majesté et de noblesse. »", "ref": "Coran, sourate Ar-Rahmân (55), verset 27.", "degre": "coran", "texte": "Autre référence : Coran, sourate Al-Qasas (28), verset 88, qui rappelle que toute chose périra sauf Allah.\n\nPrécision : Ces versets attestent la permanence d'Allah. Ils n'emploient pas exactement la forme nominale « Al-Bâqî »."}, {"type": "texte", "titre": "Quand évoquer cette appellation", "texte": "Lorsqu'on médite sur le caractère éphémère de la vie, qu'on souhaite se détacher des biens matériels ou qu'on demande à Allah une bonne fin."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Toi qui demeures éternellement, aide-moi à consacrer mes actes à ce qui a de la valeur auprès de Toi. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "STATUT DISCUTÉ", "texte": "Sens de la permanence explicitement attesté dans le Coran ; statut de « Al-Bâqî » comme Nom indépendant discuté. Mention de prudence."}], "numero_source": 95}$fiche$::jsonb where display_order = 96 and transliteration = 'Al-Bâqî' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الْوَارِثُ", "translit": "Al-Wârith", "traduction": "L'Héritier ultime, Celui à qui toute chose revient.", "provenance": "Coran — attesté explicitement.", "statut": "etabli", "classement": "coran", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est Al-Wârith. Lorsque les créatures disparaissent, Allah demeure. Tout ce qu'elles possédaient revient finalement à Lui, car Il est le véritable Maître de toute chose.\n\nLes possessions humaines sont temporaires. Nous ne sommes que dépositaires de ce qu'Allah nous accorde pendant notre vie.\n\nCe Nom nous rappelle que rien de ce que nous possédons ne nous appartient de manière absolue."}, {"type": "texte", "titre": "Ce que ce Nom nous enseigne", "texte": "- Ne pas s'attacher excessivement aux biens matériels.\n- Utiliser nos biens de manière responsable.\n- Être généreux et faire le bien tant que nous en avons la possibilité.\n- Se rappeler que notre retour final est vers Allah."}, {"type": "preuve", "titre": "Preuve dans le Coran", "arabe": "وَإِنَّا لَنَحْنُ نُحْيِي وَنُمِيتُ وَنَحْنُ الْوَارِثُونَ", "traduction": "« C'est Nous qui donnons la vie et donnons la mort, et c'est Nous qui sommes les héritiers. »", "ref": "Coran, sourate Al-Hijr (15), verset 23.", "degre": "coran", "texte": null}, {"type": "texte", "titre": "Quand invoquer Allah par ce Nom", "texte": "Lorsqu'on souhaite se détacher de l'excès d'attachement aux biens matériels, demander à Allah une bonne fin ou Lui confier ce que l'on possède."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, Al-Wârith, aide-moi à utiliser les bienfaits que Tu m'as accordés dans ce qui Te satisfait et fais que mes œuvres soient bénéfiques après ma mort. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "CORAN", "texte": "Attesté explicitement dans le Coran."}], "numero_source": 96}$fiche$::jsonb where display_order = 97 and transliteration = 'Al-Wârith' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الرَّشِيدُ", "translit": "Ar-Rashîd", "traduction": "Celui qui guide vers la justesse et dont la sagesse est parfaite.", "provenance": "Sens de guidance et de sagesse attesté dans le Coran ; Nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Cette appellation évoque la perfection de la sagesse divine et la guidance vers ce qui est juste.\n\nAllah ne se trompe jamais dans Ses décisions. Sa connaissance est parfaite et Sa sagesse ne comporte aucune imperfection.\n\nLa forme exacte « Ar-Rashîd » figure dans certaines listes traditionnelles des 99 noms. Cependant, son établissement comme Nom divin indépendant à partir d'une preuve explicite du Coran ou d'un hadith authentique clair est discuté.\n\nIl faut donc distinguer le sens de sagesse et de guidance, qui est bien attesté dans les textes, du statut de cette appellation comme Nom indépendant."}, {"type": "texte", "titre": "Ce que cette appellation nous rappelle", "texte": "- Reconnaître que la sagesse parfaite appartient à Allah.\n- Lui demander de nous guider dans nos décisions.\n- Ne pas confondre nos opinions personnelles avec la vérité.\n- Rechercher les conseils et les connaissances fiables.\n- Accepter que notre compréhension soit limitée."}, {"type": "preuve", "titre": "Preuve liée au sens dans le Coran", "arabe": "وَمَا تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ", "traduction": "« Ma réussite ne dépend que d'Allah. En Lui je place ma confiance et c'est vers Lui que je reviens repentant. »", "ref": "Coran, sourate Hûd (11), verset 88.", "degre": "coran", "texte": "Précision : Ce verset affirme que la réussite et la bonne orientation dépendent d'Allah, mais ne contient pas le Nom exact « Ar-Rashîd »."}, {"type": "texte", "titre": "Quand évoquer cette appellation", "texte": "Lorsqu'on demande à Allah de nous guider vers la bonne décision, de nous préserver des erreurs et de nous accorder la sagesse."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, guide-moi vers ce qui est juste, accorde-moi la sagesse et préserve-moi des décisions qui pourraient m'éloigner de Toi. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "STATUT DISCUTÉ", "texte": "Sens général de guidance et de sagesse attesté dans le Coran ; statut de « Ar-Rashîd » comme Nom divin indépendant discuté. Mention de prudence."}], "numero_source": 97}$fiche$::jsonb where display_order = 98 and transliteration = 'Ar-Rashîd' and fiche_adulte is null;
update public.allah_names set fiche_adulte = $fiche${"nom_arabe": "الصَّبُورُ", "translit": "As-Sabûr", "traduction": "Le Très Patient, Celui dont la patience est parfaite.", "provenance": "Patience divine attestée dans la Sunna authentique ; Nom indépendant discuté.", "statut": "divergence", "classement": "discute", "sections": [{"type": "texte", "titre": "Explication", "texte": "Allah est parfaitement patient. Il ne se précipite pas dans la punition de Ses serviteurs malgré leurs fautes. Il leur accorde du temps, leur ouvre la porte du repentir et leur permet de revenir vers Lui.\n\nLa patience d'Allah n'est pas comparable à celle des créatures. Elle n'est pas due à une incapacité ou à une faiblesse : Allah est parfaitement puissant et agit selon Sa sagesse.\n\nLa forme exacte « As-Sabûr » est présente dans certaines listes traditionnelles des 99 noms. Il faut toutefois être prudent : le hadith authentique décrit Allah comme Celui qui fait preuve d'une patience immense face aux paroles blessantes que les gens Lui attribuent, mais cela ne suffit pas à établir automatiquement la forme nominale « As-Sabûr » comme Nom divin indépendant."}, {"type": "texte", "titre": "Ce que cette appellation nous rappelle", "texte": "- Ne pas désespérer de la miséricorde d'Allah.\n- Comprendre que le délai accordé à une personne ne signifie pas qu'Allah ignore ses actes.\n- Apprendre à être patient dans l'obéissance et face aux épreuves.\n- Éviter de se précipiter dans nos jugements.\n- Revenir sincèrement vers Allah."}, {"type": "preuve", "titre": "Preuve dans la Sunna authentique", "arabe": null, "traduction": null, "ref": "- Sahih Al-Bukhârî, hadith 6099.\n- Sahih Muslim, hadith 2804.", "degre": "sahih", "texte": "Le Prophète ﷺ a dit qu'aucun être ne fait preuve d'une patience comparable à celle d'Allah face aux paroles blessantes que les gens Lui attribuent : ils Lui attribuent un enfant, alors qu'Il leur accorde malgré cela la santé et la subsistance.\n\nAuthenticité : Hadith authentique rapporté par Al-Bukhârî et Muslim.\n\nPrécision importante : Le hadith décrit la patience d'Allah, mais ne contient pas exactement le Nom « As-Sabûr ». Son statut comme Nom divin indépendant doit donc être signalé avec prudence."}, {"type": "texte", "titre": "Quand évoquer cette appellation", "texte": "Lorsqu'on souhaite demander à Allah de nous aider à patienter, de nous accorder la persévérance dans l'obéissance et de nous préserver de la précipitation."}, {"type": "invocation", "titre": "Exemple d'invocation personnelle", "texte": "« Ô Allah, accorde-moi la patience dans les épreuves, la constance dans l'obéissance et un cœur qui ne désespère jamais de Ta miséricorde. »", "note": null}, {"type": "authenticite", "titre": "Authenticité du Nom", "badge": "STATUT DISCUTÉ", "texte": "La patience parfaite d'Allah est évoquée dans un hadith authentique. La forme « As-Sabûr » comme Nom divin indépendant est discutée. Mention de prudence."}], "numero_source": 98}$fiche$::jsonb where display_order = 99 and transliteration = 'As-Sabûr' and fiche_adulte is null;

update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الرَّحْمَٰنُ", "translit": "Ar-Rahmân", "statut": "etabli", "sens": "Allah a une très grande miséricorde, pour toutes Ses créatures.", "comme": "Quand je me réveille en bonne santé, c'est un cadeau de la miséricorde d'Allah.", "faire": "Je suis doux et gentil avec les autres.", "dire": "Ô Allah, Ar-Rahmân, fais-moi miséricorde.", "dire_type": "personnelle", "prudence": null, "a_relire": true}$fiche$::jsonb where display_order = 1 and transliteration = 'Ar-Rahmân' and fiche_enfant is null;
update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الرَّحِيمُ", "translit": "Ar-Rahîm", "statut": "etabli", "sens": "Allah est très miséricordieux avec ceux qui croient en Lui.", "comme": "Quand j'ai fait une erreur, je peux demander pardon à Allah.", "faire": "Je pardonne à mon copain qui m'a fait de la peine.", "dire": "Ô Allah, Ar-Rahîm, pardonne-moi.", "dire_type": "personnelle", "prudence": null, "a_relire": true}$fiche$::jsonb where display_order = 2 and transliteration = 'Ar-Rahîm' and fiche_enfant is null;
