update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الْمُؤْمِنُ", "translit": "Al-Mu'min", "statut": "etabli", "sens": "Allah donne la sécurité, et Il dit toujours la vérité.", "comme": "Quand je suis inquiet, je peux faire confiance à Allah.", "faire": "Je place ma confiance en Allah.", "dire": "Ô Allah, Al-Mu'min, donne-moi la sécurité.", "dire_type": "personnelle", "prudence": null, "a_relire": true}$fiche$::jsonb where display_order = 6 and transliteration = 'Al-Mu''min' and fiche_enfant is null;
