update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الْمُصَوِّرُ", "translit": "Al-Musawwir", "statut": "etabli", "sens": "Allah donne à chaque créature sa forme et son apparence.", "comme": "Quand je vois des enfants tous différents, je pense à Allah qui leur a donné leur forme.", "faire": "Je ne me moque jamais de l'apparence des autres.", "dire": "Ô Allah, Al-Musawwir, embellis mon cœur par la foi.", "dire_type": "personnelle", "prudence": null, "a_relire": true}$fiche$::jsonb where display_order = 13 and transliteration = 'Al-Musawwir' and fiche_enfant is null;
