update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الْبَاسِطُ", "translit": "Al-Bâsit", "statut": "divergence", "sens": "Allah peut donner beaucoup et rendre les choses faciles.", "comme": "Quand j'ai beaucoup de bonnes choses, je remercie Allah.", "faire": "Je partage quand j'ai beaucoup.", "dire": "Ô Allah, donne-moi de bonnes choses et facilite-moi.", "dire_type": "personnelle", "prudence": "Les savants ne sont pas tous d'accord pour dire que c'est un nom d'Allah.", "a_relire": true}$fiche$::jsonb where display_order = 21 and transliteration = 'Al-Bâsit' and fiche_enfant is null;
