update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الْبَدِيعُ", "translit": "Al-Badî'", "statut": "etabli", "sens": "Allah a créé les cieux et la terre sans modèle.", "comme": "Quand je regarde un arc-en-ciel, je pense à Allah qui a tout créé.", "faire": "J'admire la création d'Allah.", "dire": "Ô Allah, Al-Badî', guide-moi vers le bien.", "dire_type": "personnelle", "prudence": null, "a_relire": true}$fiche$::jsonb where display_order = 95 and transliteration = 'Al-Badî''' and fiche_enfant is null;
update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الْبَاقِي", "translit": "Al-Bâqî", "statut": "divergence", "sens": "Allah reste pour toujours. Tout le reste finira.", "comme": "Quand mon jouet se casse, je me rappelle que les choses ne durent pas.", "faire": "Je fais des choses qui plaisent à Allah.", "dire": "Ô Allah, aide-moi à faire ce qui Te plaît.", "dire_type": "personnelle", "prudence": "Les savants ne sont pas tous d'accord pour dire que c'est un nom d'Allah.", "a_relire": true}$fiche$::jsonb where display_order = 96 and transliteration = 'Al-Bâqî' and fiche_enfant is null;
update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الْوَارِثُ", "translit": "Al-Wârith", "statut": "etabli", "sens": "Tout revient à Allah à la fin, car tout Lui appartient.", "comme": "Quand je prête mes jouets, je me rappelle que tout appartient à Allah.", "faire": "Je prends soin de mes affaires et je partage.", "dire": "Ô Allah, Al-Wârith, aide-moi à être généreux.", "dire_type": "personnelle", "prudence": null, "a_relire": true}$fiche$::jsonb where display_order = 97 and transliteration = 'Al-Wârith' and fiche_enfant is null;
update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الرَّشِيدُ", "translit": "Ar-Rashîd", "statut": "divergence", "sens": "Allah guide vers ce qui est juste, et Sa sagesse est parfaite.", "comme": "Quand je dois choisir, je demande à Allah de me guider.", "faire": "Je demande conseil à mes parents.", "dire": "Ô Allah, guide-moi vers ce qui est juste.", "dire_type": "personnelle", "prudence": "Les savants ne sont pas tous d'accord pour dire que c'est un nom d'Allah.", "a_relire": true}$fiche$::jsonb where display_order = 98 and transliteration = 'Ar-Rashîd' and fiche_enfant is null;
update public.allah_names set fiche_enfant = $fiche${"nom_arabe": "الصَّبُورُ", "translit": "As-Sabûr", "statut": "divergence", "sens": "Allah est très patient : Il laisse aux gens le temps de revenir vers Lui.", "comme": "Quand mon petit frère m'énerve, j'essaie d'être patient.", "faire": "Je reste patient.", "dire": "Ô Allah, donne-moi la patience.", "dire_type": "personnelle", "prudence": "Les savants ne sont pas tous d'accord pour dire que c'est un nom d'Allah.", "a_relire": true}$fiche$::jsonb where display_order = 99 and transliteration = 'As-Sabûr' and fiche_enfant is null;
select count(*) filter (where fiche_adulte is not null) as fiches_adultes, count(*) filter (where fiche_enfant is not null) as fiches_enfants from public.allah_names;
